const __pageData = JSON.parse('{"title":"第 1 章：先跑通一个最小 TinyLLM","description":"不讲原理，先用不到 100 行 PyTorch 把“文本 → 编号 → 模型 → 损失 → 更新 → 生成”整条流水线跑一遍。","frontmatter":{"title":"第 1 章：先跑通一个最小 TinyLLM","description":"不讲原理，先用不到 100 行 PyTorch 把“文本 → 编号 → 模型 → 损失 → 更新 → 生成”整条流水线跑一遍。","pageClass":"tinyllm-course"},"headers":[],"relativePath":"tinyllm/first-run.md","filePath":"tinyllm/first-run.md"}');
